// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Bound value to avoid excessive gas or revert due to insufficient balance
        value = bound(value, 0, address(c).balance);
        // Record the deployer's address (msg.sender of the constructor)
        address expectedOwner = address(this);
        // Drive the contract via sendMoney
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        // Assert that owner still equals expectedOwner after the call (success or not)
        assertTrue(c.owner() == expectedOwner);
    }
}

